	for k, v := range blindedTokens {
		cBlindedTokens[k] = v.raw
	}
	cSignedTokens := make([]*C.C_SignedToken, len(signedTokens), len(signedTokens))
	for k, v := range signedTokens {
		cSignedTokens[k] = v.raw
