            if !s.is_null() {
                let slice = slice::from_raw_parts(s, s_length);

                match str::from_utf8(slice) {
                    Ok(s_as_str) => match $t::decode_base64(s_as_str) {
                        Ok(t) => return Box::into_raw(Box::new(t)),
